      float4 b1 = float4( x.zw, y.zw );
      float4 s0 = floor(b0)*2.0 + 1.0;
      float4 s1 = floor(b1)*2.0 + 1.0;
      float4 sh = -step(h, float4(0.0));
      float4 a0 = b0.xzyw + s0.xzyw*sh.xxyy ;
      float4 a1 = b1.xzyw + s1.xzyw*sh.zzww ;
      float3 p0 = float3(a0.xy,h.x);
      float3 p1 = float3(a0.zw,h.y);
      float3 p2 = float3(a1.xy,h.z);
      float3 p3 = float3(a1.zw,h.w);
      float4 norm = taylorInvSqrt(float4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
      p0 *= norm.x;
      p1 *= norm.y;
      p2 *= norm.z;
      p3 *= norm.w;
      x0.xy *= rot(amzLocal_time*checkersign(a0.xy));
      x1.xy *= rot(amzLocal_time*checkersign(a0.zw));
      x2.xy *= rot(amzLocal_time*checkersign(a1.xy));
      x3.xy *= rot(amzLocal_time*checkersign(a1.zw));
      float4 m = max(0.6 - float4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
      float4 m2 = m * m;
      float4 m4 = m2 * m2;
      float4 pdotx = float4(dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3));
      float4 temp = m2 * m * pdotx;
      gradient = -8.0 * (temp.x * x0 + temp.y * x1 + temp.z * x2 + temp.w * x3);
      gradient += m4.x * p0 + m4.y * p1 + m4.z * p2 + m4.w * p3;
      gradient *= 42.0;
      return 42.0 * dot(m4, pdotx);
    }
