    float snoise(float3 v, out float3 gradient, float amzLocal_time)
    {
      const float2 C = float2(1.0/6.0, 1.0/3.0) ;
      const float4 D = float4(0.0, 0.5, 1.0, 2.0);
      float3 i = floor(v + dot(v, C.yyy) );
      float3 x0 = v - i + dot(i, C.xxx) ;
      float3 g = step(x0.yzx, x0.xyz);
      float3 l = 1.0 - g;
      float3 i1 = min( g.xyz, l.zxy );
      float3 i2 = max( g.xyz, l.zxy );
      float3 x1 = x0 - i1 + C.xxx;
      float3 x2 = x0 - i2 + C.yyy;
      float3 x3 = x0 - D.yyy;
      i = mod289(i);
      float4 p = permute( permute( permute(
                 i.z + float4(0.0, i1.z, i2.z, 1.0 ))
               + i.y + float4(0.0, i1.y, i2.y, 1.0 ))
               + i.x + float4(0.0, i1.x, i2.x, 1.0 ));
      float n_ = 0.142857142857;
      float3 ns = n_ * D.wyz - D.xzx;
      float4 j = p - 49.0 * floor(p * ns.z * ns.z);
      float4 x_ = floor(j * ns.z);
      float4 y_ = floor(j - 7.0 * x_ );
      float4 x = x_ *ns.x + ns.yyyy;
      float4 y = y_ *ns.x + ns.yyyy;
      float4 h = 1.0 - abs(x) - abs(y);
      float4 b0 = float4( x.xy, y.xy );
      float4 b1 = float4( x.zw, y.zw );
      float4 s0 = floor(b0)*2.0 + 1.0;
      float4 s1 = floor(b1)*2.0 + 1.0;
      float4 sh = -step(h, float4(0.0));
      float4 a0 = b0.xzyw + s0.xzyw*sh.xxyy ;
      float4 a1 = b1.xzyw + s1.xzyw*sh.zzww ;
      float3 p0 = float3(a0.xy,h.x);
      float3 p1 = float3(a0.zw,h.y);
      float3 p2 = float3(a1.xy,h.z);
      float3 p3 = float3(a1.zw,h.w);
      float4 norm = taylorInvSqrt(float4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
      p0 *= norm.x;
      p1 *= norm.y;
      p2 *= norm.z;
      p3 *= norm.w;
      x0.xy *= rot(amzLocal_time*checkersign(a0.xy));
      x1.xy *= rot(amzLocal_time*checkersign(a0.zw));
      x2.xy *= rot(amzLocal_time*checkersign(a1.xy));
      x3.xy *= rot(amzLocal_time*checkersign(a1.zw));
      float4 m = max(0.6 - float4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
      float4 m2 = m * m;
      float4 m4 = m2 * m2;
      float4 pdotx = float4(dot(p0,x0), dot(p1,x1), dot(p2,x2), dot(p3,x3));
      float4 temp = m2 * m * pdotx;
      gradient = -8.0 * (temp.x * x0 + temp.y * x1 + temp.z * x2 + temp.w * x3);
      gradient += m4.x * p0 + m4.y * p1 + m4.z * p2 + m4.w * p3;
      gradient *= 42.0;
      return 42.0 * dot(m4, pdotx);
    }
    void amzRender()
    {
        float4 texColor = amzTexture(0,amzScreenNorm());
        float4 texColorX = float4(0.0,0.0,0.0,1.0) * texColor.a;
        float2 image_size = getTexSize((screen.zw/1.0));
        float maxF = max(screen.zw.x, screen.zw.y);
        float2 texelSize = 1.0 / float2(maxF, maxF);
        float2 satriyaid;
        satriyaid = ((float2(amzScreenNorm().x,1.0-amzScreenNorm().y)*screen.zw)-amzLayerCenter())/layer;
        satriyaid.y*=layer.y/layer.x;
        satriyaid /= amzp_scale;
        satriyaid *= rot2m((0.0)*0.0174533);
        satriyaid += float2((0.0+amzp_position.x), (0.0+amzp_position.y))*float2(-1.,1.)/500.;
        float2 scaleVec;
        scaleVec = float2(amzp_scale*amzp_stretch.x,amzp_scale*amzp_stretch.y);
        satriyaid /= scaleVec;
         float4 fragColor;
         float amzLocal_time = (amzp_autop>0.5)? (amzp_EVO*0.5)+(time*0.01) * 12.0 : amzp_EVO*0.5;
         float2 resolution = float2(screen.zw.x, screen.zw.y);
         float2 uv = satriyaid;
         float2 uv2 = uv;
         uv += float2(0.5);
         uv.x = uv.x * screen.zw.x / screen.zw.y;
         float a= amzp_kangle * 3.1415926 / 180.0;
         float si=sin(a),co=cos(a);
         uv*=float2x2(co,-si,si,co);
         uv*=length(uv+float2(0.0,8.0))*.5+1.;
         uv -= float2(0.5);
         float3 c=amzp_kcolor.rgb;
         float v=1.-sin(hash(floor(uv.x*100.))*2.);
         float b=clamp(abs(sin(20.*amzLocal_time*v+uv.y*(5./(3.+amzp_klength +v))))-.95,0.,1.)*10. * amzp_kalpha;
         c*=v*b ;
         float4 albedo = amzTexture(0,uv2);
         fragColor = float4(c, 1.0);
     float4 factor = mix(texColorX,fragColor,1.0);
        float4 resultfinal;
        if( int(amzp_blendMode)==0 ) {
            resultfinal = (factor * amzp_bright) * texColor.a;
        } else if( int(amzp_blendMode)==1 ) {
            factor *= amzp_bright;
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( int(amzp_blendMode)==2 ) {
            factor *= amzp_bright;
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }
     amzOutput = mix(texColor, resultfinal, amzp_alpha);
    }

